// todo-board — what Claude is working on, what is blocked, and what is
// waiting on YOU.
//
// The tasks are not kept in plugin state. They live in a plain JSON file
// (.claude/todo-board.json) so Claude can update them with an ordinary file
// edit, mid-task, without a tool for it -- and so the board survives /clear,
// /resume and a new session, which plugin state does not. The board is the
// file; this module only draws it.

import { atom, read, update } from 'claude-code'

const PANE = 'todo-board'
const BOARD_FILE = '.claude/todo-board.json'

const board = atom({ plugin: 'todo-board', key: 'board' }, null)
const boardError = atom({ plugin: 'todo-board', key: 'error' }, '')

// Order matters: this is the reading order of the board. "blocked" sits first
// because a blocked task is the one that needs someone, and a board that
// buried it under in-progress work would be a worse version of saying nothing.
const ORDER = ['blocked', 'doing', 'todo', 'done']
const MARK = { blocked: '!', doing: '>', todo: '·', done: '+' }
const COLOR = { blocked: 'red', doing: 'yellow', todo: undefined, done: 'green' }
const LABEL = { blocked: 'blocked', doing: 'in progress', todo: 'queued', done: 'done' }

function tasksOf(value) {
  if (!value || !Array.isArray(value.tasks)) return []
  return value.tasks.filter((t) => t && typeof t.title === 'string')
}

function tally(tasks) {
  const counts = { blocked: 0, doing: 0, todo: 0, done: 0, onYou: 0 }
  for (const t of tasks) {
    if (counts[t.status] !== undefined) counts[t.status] += 1
    // Done is done: a finished task waiting on nobody must not be counted as
    // needing the reader, or the board cries wolf and stops being read.
    if (t.owner === 'user' && t.status !== 'done') counts.onYou += 1
  }
  return counts
}

async function loadBoard($) {
  try {
    const raw = await $.fs.read(BOARD_FILE)
    if (typeof raw !== 'string' || raw.trim() === '') {
      await update($, boardError, () => BOARD_FILE + ' is empty')
      await update($, board, () => null)
      return
    }
    const parsed = JSON.parse(raw)
    await update($, boardError, () => '')
    await update($, board, () => parsed)
  } catch (err) {
    // A board that cannot be read must say so. Rendering an empty board here
    // would claim there is nothing to do, which is the opposite of unknown.
    await update($, boardError, () => String(err?.message || err).slice(0, 300))
    await update($, board, () => null)
  }
}

export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'todo',
      description: 'The board: what Claude is on, what is blocked, what is waiting on you',
    })
    // Read it up front so the spinner can carry the count before anyone opens
    // the pane -- the board is most useful when it is noticed unprompted.
    await loadBoard($)
    return next(e)
  })

  on('command.run', { command: 'todo' }, async ($) => {
    await loadBoard($)
    await $.ui.open({ id: PANE, title: 'Todo board', focus: true, closeOnEscape: true })
    return {}
  })

  // Surface the one number worth interrupting for: how much is stuck on them.
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    const value = await read($, board)
    const tasks = tasksOf(value)
    if (tasks.length === 0) return next(e)
    const t = tally(tasks)
    const parts = []
    if (t.onYou > 0) parts.push(t.onYou + ' on you')
    if (t.doing > 0) parts.push(t.doing + ' running')
    if (parts.length === 0) return next(e)
    return next({ ...e, props: { ...e.props, suffix: ' · todo ' + parts.join(', ') } })
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    const width = Math.max(32, Number(e.props?.bodyColumns) || 60)
    const value = await read($, board)
    const err = await read($, boardError)
    const tasks = tasksOf(value)

    if (err) {
      return Box({
        flexDirection: 'column',
        children: [
          Text({ bold: true, children: ['Todo board'] }),
          Text({ color: 'red', wrap: 'wrap', children: [err] }),
          Text({ dimColor: true, wrap: 'wrap', children: ['The board is ' + BOARD_FILE + ', relative to the session directory.'] }),
        ],
      })
    }
    if (tasks.length === 0) {
      return Box({
        flexDirection: 'column',
        children: [
          Text({ bold: true, children: ['Todo board'] }),
          Text({ dimColor: true, wrap: 'wrap', children: ['No tasks on the board yet. Claude adds them as work arrives; ask for anything and it lands here.'] }),
        ],
      })
    }

    const t = tally(tasks)
    const header = [Text({ bold: true, children: ['Todo board'] })]
    if (t.onYou > 0) header.push(Text({ color: 'red', bold: true, children: [t.onYou + ' waiting on you'] }))
    if (t.doing > 0) header.push(Text({ color: 'yellow', children: [t.doing + ' in progress'] }))
    if (t.todo > 0) header.push(Text({ dimColor: true, children: [t.todo + ' queued'] }))
    if (t.done > 0) header.push(Text({ color: 'green', children: [t.done + ' done'] }))

    const rows = []
    const rule = (label) =>
      Text({ dimColor: true, children: [label + ' ' + '─'.repeat(Math.max(1, width - label.length - 1))] })

    for (const status of ORDER) {
      const group = tasks.filter((x) => x.status === status)
      if (group.length === 0) continue
      rows.push(rule(LABEL[status] + ' (' + group.length + ')'))
      for (const task of group) {
        rows.push(
          Box({
            flexDirection: 'row',
            columnGap: 1,
            children: [
              Text({ color: COLOR[status], children: [MARK[status] || '·'] }),
              Text({ dimColor: true, children: [task.id || ''] }),
              Text({ bold: status !== 'done', wrap: 'truncate-end', children: [task.title] }),
              // Say who it is stuck on, but only while it is still stuck.
              ...(task.owner === 'user' && status !== 'done'
                ? [Text({ color: 'red', children: ['[you]'] })]
                : []),
              ...(task.source === 'user' ? [Text({ dimColor: true, children: ['(asked)'] })] : []),
            ],
          }),
        )
        // The note is the state, not a description: what was measured, what is
        // actually in the way. It is the reason this board beats a list.
        if (task.note) {
          rows.push(Text({ dimColor: true, wrap: 'wrap', children: ['    ' + task.note] }))
        }
      }
    }

    return Box({
      flexDirection: 'column',
      children: [
        Box({ flexDirection: 'row', columnGap: 2, children: header }),
        Text({ children: [' '] }),
        ...rows,
        Text({ children: [' '] }),
        Text({ dimColor: true, children: ['board: ' + BOARD_FILE + (value?.updated ? '  ·  updated ' + value.updated : '')] }),
      ],
    })
  })
}

import { expect, test } from 'claude-code/testing'

const PANE = {
  plugin: 'todo-board',
  component: 'Pane',
  requestId: 'todo-board',
  surface: 'terminal',
  viewport: { columns: 120, rows: 40 },
  props: {
    title: 'Todo board',
    isFocused: true,
    bodyColumns: 72,
    placement: 'inline',
    scroll: { offset: 0, bodyRows: 30 },
    view: {},
  },
} as const

const boardJson = (tasks: unknown[]) => JSON.stringify({ updated: '2026-10-11', tasks })

function harness(on, file: string | (() => never)) {
  on('command.register', () => ({ value: undefined }))
  on('session.start', () => ({ cwd: '/work' }))
  on('ui.open', () => ({ value: { isPlaced: true } }))
  on('ui.render', () => ({ type: 'Text', props: {}, children: ['drawn by Claude Code'] }))
  on('fs.read', () => {
    if (typeof file === 'function') return file()
    return { value: file }
  })
}

test('/todo reads the board file and opens the pane', async ($, on) => {
  const opened: unknown[] = []
  harness(on, boardJson([{ id: 'T-01', title: 'Ship the thing', status: 'doing', owner: 'claude', source: 'user' }]))
  on('ui.open', ($, e) => {
    opened.push(e)
    return { value: { isPlaced: true } }
  })

  const answer = await $.command.run({ command: 'todo', args: '' })
  expect(answer).toEqual({})
  expect(opened).toMatchObject([{ id: 'todo-board', title: 'Todo board' }])

  const ui = await $.ui.mount(PANE)
  expect(await ui.find({ type: 'Text', text: 'Ship the thing' })).toBeDefined()
})

// A board that cannot be read must SAY so. Drawing an empty board would claim
// there is nothing to do, which is a different and much worse statement than
// "I could not look" -- the same false-negative this whole family of panes
// exists to prevent.
test('an unreadable board reports the error instead of claiming nothing to do', async ($, on) => {
  harness(on, () => {
    throw new Error('ENOENT: no such file')
  })

  await $.command.run({ command: 'todo', args: '' })
  const ui = await $.ui.mount(PANE)

  expect(await ui.find({ type: 'Text', text: /ENOENT/ })).toBeDefined()
  expect(await ui.find({ type: 'Text', text: /No tasks on the board yet/ })).toBeUndefined()
})

test('malformed JSON is an error, not an empty board', async ($, on) => {
  harness(on, '{ "tasks": [ ')
  await $.command.run({ command: 'todo', args: '' })
  const ui = await $.ui.mount(PANE)
  expect(await ui.find({ type: 'Text', text: /No tasks on the board yet/ })).toBeUndefined()
})

// The whole reason the board beats a list: it says what is stuck on the person
// reading it. A blocked task buried under in-progress work is a worse version
// of not saying anything.
test('what is waiting on you is counted and shown first', async ($, on) => {
  harness(
    on,
    boardJson([
      { id: 'T-01', title: 'Running now', status: 'doing', owner: 'claude', source: 'user' },
      { id: 'T-02', title: 'Needs your approval', status: 'blocked', owner: 'user', source: 'proactive' },
      { id: 'T-03', title: 'Queued work', status: 'todo', owner: 'claude', source: 'proactive' },
    ]),
  )

  await $.command.run({ command: 'todo', args: '' })
  const ui = await $.ui.mount(PANE)

  expect(await ui.find({ type: 'Text', text: '1 waiting on you' })).toBeDefined()
  expect(await ui.find({ type: 'Text', text: '[you]' })).toBeDefined()

  const text = JSON.stringify(await ui.snapshot())
  // Blocked must be rendered before in-progress, or the urgent row scrolls away.
  expect(text.indexOf('Needs your approval')).toBeLessThan(text.indexOf('Running now'))
})

// A finished task waiting on nobody must not be counted as needing the reader,
// or the board cries wolf and stops being read.
test('a done task owned by you is not still waiting on you', async ($, on) => {
  harness(
    on,
    boardJson([
      { id: 'T-01', title: 'You already approved this', status: 'done', owner: 'user', source: 'user' },
      { id: 'T-02', title: 'This one still needs you', status: 'blocked', owner: 'user', source: 'user' },
    ]),
  )

  await $.command.run({ command: 'todo', args: '' })
  const ui = await $.ui.mount(PANE)

  expect(await ui.find({ type: 'Text', text: '1 waiting on you' })).toBeDefined()
  expect(await ui.find({ type: 'Text', text: '2 waiting on you' })).toBeUndefined()
})

// The note is the state -- what was measured, what is actually in the way.
// Without it the board is a list of titles, which nobody needs.
test('each task carries its current state, not just a title', async ($, on) => {
  harness(
    on,
    boardJson([
      {
        id: 'T-06',
        title: 'Shared hosted brain',
        status: 'blocked',
        owner: 'user',
        source: 'user',
        note: 'server stack is 1,824 commits behind main',
      },
    ]),
  )

  await $.command.run({ command: 'todo', args: '' })
  const ui = await $.ui.mount(PANE)
  expect(await ui.find({ type: 'Text', text: /1,824 commits behind main/ })).toBeDefined()
})

// The board is most useful when it is noticed unprompted, so the count rides
// the spinner without anyone opening the pane.
test('the spinner carries what is waiting on you', async ($, on) => {
  harness(
    on,
    boardJson([{ id: 'T-02', title: 'Needs you', status: 'blocked', owner: 'user', source: 'proactive' }]),
  )
  await $.command.run({ command: 'todo', args: '' })

  const spinner = await $.ui.render({
    plugin: 'todo-board',
    component: 'Spinner',
    surface: 'terminal',
    props: {},
  })
  expect(JSON.stringify(spinner)).toContain('1 on you')
})

