// --- the exploration signal ---------------------------------------------------
// The gap this closes was measured, not imagined: 43 brain calls in a long
// session, zero of them retrieval, in a repo whose guide says ALWAYS brief
// first. A guide is read once at the start; this arrives while the choice is
// being made, which is the only place it can change anything.

function exploreHarness(on) {
  const lines: string[] = []
  on('command.register', () => ({ value: undefined }))
  on('session.start', () => ({ cwd: '/work' }))
  on('turn.start', ($, e) => ({ turnId: e.turnId }))
  on('ui.open', () => ({ value: { isPlaced: true } }))
  on('ui.render', ($, e) => ({ type: 'Text', props: {}, children: ['drawn'] }))
  on('ui.log', ($, e) => {
    lines.push(e.text)
    return { value: undefined }
  })
  on('tool.call', () => ({ result: '' }))
  return lines
}

const nudges = (lines: string[]) => lines.filter((l) => l.includes('0 brain calls'))

test('a turn that searches hard and asks nothing is told once', async ($, on) => {
