package cli

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"strings"
)

// Preserving fields this build does not declare, rather than refusing to write.
//
// A field RETIRED from the struct without a schema bump used to make every
// manifest the older build wrote permanently unwritable: writers refuse such a
// manifest on purpose, because re-encoding from a struct that never saw the
// field would erase what another build recorded. The refusal was right; the
// absence of any way out was not. On this machine it blacked out eleven brains,
// including two real ones, and drove a two-hour relaunch chain per repository.
//
// Carrying the unknown bytes through the write removes the dilemma: nothing is
// erased, and nothing is refused.
//
// Deliberately NOT done by giving exportManifest a MarshalJSON: that type has
// well over a hundred references and golden fixtures, and changing how it
// encodes everywhere is a far larger blast radius than this problem warrants.
// The merge happens at the one place that replaces the file on disk.

// manifestDeclaredKeys is the set of top-level JSON keys exportManifest knows.
// Derived by reflection so it cannot drift from the struct: a field added or
// retired changes this set in the same commit.
func manifestDeclaredKeys() map[string]bool {
	keys := map[string]bool{}
	t := reflect.TypeOf(exportManifest{})
	for i := 0; i < t.NumField(); i++ {
		tag := t.Field(i).Tag.Get("json")
		if tag == "" || tag == "-" {
			continue
		}
		if name := strings.Split(tag, ",")[0]; name != "" {
			keys[name] = true
		}
	}
	return keys
}

// unknownManifestFields returns the top-level keys present on disk that this
// build does not declare.
//
// Best effort by design: a manifest that is absent, unreadable or not an object
// yields nothing to preserve, and the caller carries on. Refusing here would
// re-create the failure this exists to remove.
func unknownManifestFields(outputDir string) map[string]json.RawMessage {
	data, err := os.ReadFile(filepath.Join(outputDir, exportManifestFileName))
	if err != nil {
		return nil
	}
	var all map[string]json.RawMessage
	if err := json.Unmarshal(data, &all); err != nil {
		return nil
	}
	declared := manifestDeclaredKeys()
	unknown := map[string]json.RawMessage{}
	for k, v := range all {
		if !declared[k] {
			unknown[k] = v
		}
	}
	if len(unknown) == 0 {
		return nil
	}
	return unknown
}

// mergeUnknownManifestFields re-attaches preserved keys to freshly encoded
// manifest bytes.
//
// A declared key always wins: this build owns the fields it knows about, and a
// stale copy of one must never overwrite what the caller just computed. Only
// keys the struct does not model are carried through.
func mergeUnknownManifestFields(encoded []byte, unknown map[string]json.RawMessage) ([]byte, error) {
	if len(unknown) == 0 {
		return encoded, nil
	}
	var merged map[string]json.RawMessage
	if err := json.Unmarshal(encoded, &merged); err != nil {
		return nil, err
	}
	for k, v := range unknown {
		if _, declared := merged[k]; declared {
			continue
		}
		merged[k] = v
	}
	return json.MarshalIndent(merged, "", "  ")
}
