package cli

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// The failure this removes, in full: a field RETIRED from the struct without a
// schema bump makes every manifest the older build wrote unwritable, for ever,
// because writers refuse what they cannot round-trip. On one machine that
// blacked out eleven brains -- two of them real -- and drove a 1m..30m relaunch
// chain per repository, each pending retry a live sleeping process.

func readManifestMap(t *testing.T, dir string) map[string]json.RawMessage {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(dir, exportManifestFileName))
	if err != nil {
		t.Fatalf("read manifest: %v", err)
	}
	var m map[string]json.RawMessage
	if err := json.Unmarshal(data, &m); err != nil {
		t.Fatalf("manifest is not valid JSON after the write: %v", err)
	}
	return m
}

func writeRawManifest(t *testing.T, dir string, body map[string]any) {
	t.Helper()
	data, err := json.MarshalIndent(body, "", "  ")
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	if err := os.WriteFile(filepath.Join(dir, exportManifestFileName), data, 0o600); err != nil {
		t.Fatalf("write: %v", err)
	}
}

func TestAWriteKeepsFieldsThisBuildDoesNotKnow(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	writeRawManifest(t, dir, map[string]any{
		"schema_version":      brainManifestSchemaVersion,
		"repo_key":            "local/demo",
		"suppressed_warnings": []string{"a retired field, still on disk"},
		"something_newer":     map[string]any{"from": "a future build"},
	})

	err := writeBrainManifestAndReadme(dir, exportManifest{RepoKey: "local/demo", GeneratedAt: time.Now().UTC()})
	if err != nil {
		t.Fatalf("a manifest carrying unmodelled fields must still be writable: %v", err)
	}

	after := readManifestMap(t, dir)
	for _, key := range []string{"suppressed_warnings", "something_newer"} {
		if _, ok := after[key]; !ok {
			t.Errorf("%q was erased; refusing to write existed precisely to prevent that", key)
		}
	}
	if _, ok := after["repo_key"]; !ok {
		t.Error("the manifest lost a field this build DOES model")
	}
}

// The caller's value must win. A stale copy of a known field overwriting what
// was just computed would be a far worse bug than the one being fixed.
func TestAPreservedFieldNeverOverwritesAKnownOne(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	writeRawManifest(t, dir, map[string]any{
		"schema_version": brainManifestSchemaVersion,
		"repo_key":       "local/STALE",
		"retired_thing":  "keep me",
	})

	if err := writeBrainManifestAndReadme(dir, exportManifest{RepoKey: "local/fresh", GeneratedAt: time.Now().UTC()}); err != nil {
		t.Fatalf("write: %v", err)
	}

	after := readManifestMap(t, dir)
	var key string
	if err := json.Unmarshal(after["repo_key"], &key); err != nil {
		t.Fatalf("repo_key unreadable: %v", err)
	}
	if key != "local/fresh" {
		t.Fatalf("a stale on-disk value overwrote the caller's: %q", key)
	}
	if _, ok := after["retired_thing"]; !ok {
		t.Error("the unmodelled field was dropped")
	}
}

// Nothing may change for the ordinary case, or every existing manifest and
// golden fixture shifts underneath us.
func TestAnOrdinaryManifestIsUnchangedByThis(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	writeRawManifest(t, dir, map[string]any{
		"schema_version": brainManifestSchemaVersion,
		"repo_key":       "local/demo",
	})
	if err := writeBrainManifestAndReadme(dir, exportManifest{RepoKey: "local/demo"}); err != nil {
		t.Fatalf("write: %v", err)
	}
	for key := range readManifestMap(t, dir) {
		if !manifestDeclaredKeys()[key] {
			t.Errorf("a manifest with no unmodelled fields gained %q", key)
		}
	}
}

// The declared-key set is derived by reflection so it cannot drift from the
// struct. If this is empty, every field on disk looks unknown and the merge
// would duplicate the entire document.
func TestTheDeclaredKeySetIsReal(t *testing.T) {
	t.Parallel()
	keys := manifestDeclaredKeys()
	if len(keys) < 10 {
		t.Fatalf("only %d declared keys; reflection is probably broken", len(keys))
	}
	for _, want := range []string{"schema_version", "repo_key", "sessions", "generated_at"} {
		if !keys[want] {
			t.Errorf("declared key set is missing %q", want)
		}
	}
	if keys["suppressed_warnings"] {
		t.Error("a retired field is being reported as declared, so it would not be preserved")
	}
}
