// Package ledger holds the double-entry core. Every mutation is an append;
// balances are folds over the entry log, never stored.
package ledger

import "errors"

var ErrInsufficientFunds = errors.New("ledger: insufficient funds")

type Entry struct {
	Account string
	Amount  int64 // minor units; negative is a debit
	Ref     string
}

type Ledger struct{ entries []Entry }

func (l *Ledger) Append(e Entry) { l.entries = append(l.entries, e) }

func (l *Ledger) Balance(account string) int64 {
	var total int64
	for _, e := range l.entries {
		if e.Account == account {
			total += e.Amount
		}
	}
	return total
}

func (l *Ledger) Transfer(from, to string, amount int64, ref string) error {
	if l.Balance(from) < amount {
		return ErrInsufficientFunds
	}
	l.Append(Entry{Account: from, Amount: -amount, Ref: ref})
	l.Append(Entry{Account: to, Amount: amount, Ref: ref})
	return nil
}
EOF
