// Package risk scores a payment before the gateway authorises it.
package risk

type Signal struct {
	VelocityPerHour int
	NewDevice       bool
	CountryMismatch bool
}

// Score returns 0..100. Above Threshold the payment is held for review.
const Threshold = 70

func Score(s Signal) int {
	score := 0
	switch {
	case s.VelocityPerHour > 20:
		score += 50
	case s.VelocityPerHour > 5:
		score += 20
	}
	if s.NewDevice {
		score += 25
	}
	if s.CountryMismatch {
		score += 30
	}
	if score > 100 {
		score = 100
	}
	return score
}
