// Package gateway is the HTTP surface. It owns no business rules; it
// translates requests into ledger and risk calls and renders the outcome.
package gateway

import (
	"encoding/json"
	"net/http"

	"github.com/acme/payments/internal/ledger"
	"github.com/acme/payments/internal/risk"
)

type Server struct {
	mux    *http.ServeMux
	ledger *ledger.Ledger
}

func New() *Server {
	s := &Server{mux: http.NewServeMux(), ledger: &ledger.Ledger{}}
	s.mux.HandleFunc("/healthz", s.handleHealth)
	s.mux.HandleFunc("/v1/payments", s.handlePayment)
	s.mux.HandleFunc("/v1/balance", s.handleBalance)
	return s
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) { s.mux.ServeHTTP(w, r) }

func (s *Server) handleHealth(w http.ResponseWriter, _ *http.Request) {
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("ok"))
}

type paymentRequest struct {
	From, To string
	Amount   int64
	Signal   risk.Signal
}

func (s *Server) handlePayment(w http.ResponseWriter, r *http.Request) {
	var req paymentRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	if risk.Score(req.Signal) >= risk.Threshold {
		http.Error(w, "held for review", http.StatusAccepted)
		return
	}
	if err := s.ledger.Transfer(req.From, req.To, req.Amount, "api"); err != nil {
		http.Error(w, err.Error(), http.StatusPaymentRequired)
		return
	}
	w.WriteHeader(http.StatusCreated)
}

func (s *Server) handleBalance(w http.ResponseWriter, r *http.Request) {
	acct := r.URL.Query().Get("account")
	_ = json.NewEncoder(w).Encode(map[string]int64{"balance": s.ledger.Balance(acct)})
}
EOF
