func (l *liveTerminal) finish(t *refreshProgressTask, emit func()) {
	l.mu.Lock()
	defer l.mu.Unlock()
	for i, candidate := range l.stack {
		if candidate == t {
			l.stack = append(l.stack[:i], l.stack[i+1:]...)
			break
		}
	}
	l.clearLocked()
	if emit != nil {
		emit()
	}
	if len(l.stack) > 0 {
		l.paintLocked(l.stack[len(l.stack)-1], true)
	}
}

