// hasPartialEscape reports an ESC that never reaches a CSI final byte. A
// terminal handed one waits for the rest and swallows what follows.
func hasPartialEscape(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] != 0x1b {
			continue
		}
		j := i + 1
		for j < len(s) && !isANSIFinalByte(s[j]) {
			j++
		}
		if j >= len(s) {
			return true
		}
	}
