	summary = strings.TrimSuffix(strings.TrimSpace(summary), "Usage:")
	summary = strings.TrimSpace(summary)
	if runes := []rune(summary); len(runes) > MaxSummary {
		summary = strings.TrimSpace(string(runes[:MaxSummary])) + "..."
	}
	return summary
