// Package money represents amounts exactly.
package money

import (
	"errors"
	"fmt"
)

// Amount is a monetary value in the currency's MINOR units (cents, pence, yen).
//
// It is an int64 and never a float. A float64 cannot represent 0.10 exactly, so
// summing a thousand dime charges drifts away from the number the customer was
// shown, and a payments ledger that disagrees with the receipt is not a ledger.
type Amount struct {
	Minor    int64
	Currency Currency
}

// Currency is an ISO-4217 code with the exponent needed to render it.
type Currency struct {
	Code     string
	Exponent int // decimal places: USD 2, JPY 0, BHD 3
}

var (
	USD = Currency{Code: "USD", Exponent: 2}
	EUR = Currency{Code: "EUR", Exponent: 2}
	GBP = Currency{Code: "GBP", Exponent: 2}
	JPY = Currency{Code: "JPY", Exponent: 0}
)

var (
	ErrCurrencyMismatch = errors.New("money: currency mismatch")
	ErrNegative         = errors.New("money: amount must not be negative")
)

// New builds an Amount, refusing negatives. A negative charge is a refund and
// has its own type, so letting one in here would make direction ambiguous.
func New(minor int64, c Currency) (Amount, error) {
	if minor < 0 {
		return Amount{}, ErrNegative
	}
	return Amount{Minor: minor, Currency: c}, nil
}

// Add sums two amounts of the same currency.
func (a Amount) Add(b Amount) (Amount, error) {
	if a.Currency.Code != b.Currency.Code {
		return Amount{}, fmt.Errorf("%w: %s + %s", ErrCurrencyMismatch, a.Currency.Code, b.Currency.Code)
	}
	return Amount{Minor: a.Minor + b.Minor, Currency: a.Currency}, nil
}

// Sub subtracts b from a, refusing to go below zero.
func (a Amount) Sub(b Amount) (Amount, error) {
	if a.Currency.Code != b.Currency.Code {
		return Amount{}, fmt.Errorf("%w: %s - %s", ErrCurrencyMismatch, a.Currency.Code, b.Currency.Code)
	}
	if b.Minor > a.Minor {
		return Amount{}, ErrNegative
	}
	return Amount{Minor: a.Minor - b.Minor, Currency: a.Currency}, nil
}

// IsZero reports whether the amount is nothing.
func (a Amount) IsZero() bool { return a.Minor == 0 }

// String renders the amount for humans, honouring the currency exponent.
func (a Amount) String() string {
	if a.Currency.Exponent == 0 {
		return fmt.Sprintf("%d %s", a.Minor, a.Currency.Code)
	}
	div := int64(1)
	for i := 0; i < a.Currency.Exponent; i++ {
		div *= 10
	}
	return fmt.Sprintf("%d.%0*d %s", a.Minor/div, a.Currency.Exponent, a.Minor%div, a.Currency.Code)
}
EOF
