// Package store is the persistence seam for charges, refunds and ledger entries.
package store

import (
	"context"
	"errors"
	"sync"
	"time"
)

var ErrNotFound = errors.New("store: not found")

// ChargeRecord is the stored shape of a charge.
type ChargeRecord struct {
	ID             string
	IdempotencyKey string
	AmountMinor    int64
	Currency       string
	Status         string
	ProviderRef    string
	CreatedAt      time.Time
}

// RefundRecord is the stored shape of a refund against a charge.
type RefundRecord struct {
	ID          string
	ChargeID    string
	AmountMinor int64
	Currency    string
	Reason      string
	CreatedAt   time.Time
}

// Store is the interface the service depends on. Handlers never touch a
// concrete database: the webhook path and the API path must be swappable to
// in-memory in tests, because the ordering bugs this service has to survive
// are only reproducible when you control the clock and the writes.
type Store interface {
	PutCharge(ctx context.Context, c ChargeRecord) error
	GetCharge(ctx context.Context, id string) (ChargeRecord, error)
	FindChargeByIdempotencyKey(ctx context.Context, key string) (ChargeRecord, error)
	PutRefund(ctx context.Context, r RefundRecord) error
	ListRefunds(ctx context.Context, chargeID string) ([]RefundRecord, error)
}

// Memory is an in-process Store for tests and the demo.
type Memory struct {
	mu      sync.RWMutex
	charges map[string]ChargeRecord
	byKey   map[string]string
	refunds map[string][]RefundRecord
}

func NewMemory() *Memory {
	return &Memory{
		charges: map[string]ChargeRecord{},
		byKey:   map[string]string{},
		refunds: map[string][]RefundRecord{},
	}
}

func (m *Memory) PutCharge(_ context.Context, c ChargeRecord) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.charges[c.ID] = c
	if c.IdempotencyKey != "" {
		m.byKey[c.IdempotencyKey] = c.ID
	}
	return nil
}

func (m *Memory) GetCharge(_ context.Context, id string) (ChargeRecord, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	c, ok := m.charges[id]
	if !ok {
		return ChargeRecord{}, ErrNotFound
	}
	return c, nil
}

func (m *Memory) FindChargeByIdempotencyKey(_ context.Context, key string) (ChargeRecord, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	id, ok := m.byKey[key]
	if !ok {
		return ChargeRecord{}, ErrNotFound
	}
	return m.charges[id], nil
}

func (m *Memory) PutRefund(_ context.Context, r RefundRecord) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.refunds[r.ChargeID] = append(m.refunds[r.ChargeID], r)
	return nil
}

func (m *Memory) ListRefunds(_ context.Context, chargeID string) ([]RefundRecord, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return append([]RefundRecord(nil), m.refunds[chargeID]...), nil
}
EOF
