// Package ledger records what happened to money, append-only.
package ledger

import (
	"context"
	"sync"
	"time"

	"github.com/entireio/acme-payments/internal/money"
)

// Direction is which way money moved.
type Direction string

const (
	Debit  Direction = "debit"
	Credit Direction = "credit"
)

// Entry is one immutable line. Entries are NEVER updated or deleted: a refund
// is a new pair of entries, not an edit to the original charge's pair. The
// balance is therefore always derivable by replay, which is what makes a
// dispute answerable months later.
type Entry struct {
	ID        string
	ChargeID  string
	Account   string
	Direction Direction
	Amount    money.Amount
	Reason    string
	At        time.Time
}

// Journal is an append-only sequence of entries.
type Journal struct {
	mu      sync.RWMutex
	entries []Entry
}

func NewJournal() *Journal { return &Journal{} }

// Append writes entries as one atomic group. Callers pass BOTH sides of a
// double entry in a single call so a crash cannot leave a half-recorded
// movement, which would make the journal unbalanced and unreplayable.
func (j *Journal) Append(_ context.Context, entries ...Entry) error {
	j.mu.Lock()
	defer j.mu.Unlock()
	j.entries = append(j.entries, entries...)
	return nil
}

// Entries returns every line for a charge, in the order recorded.
func (j *Journal) Entries(_ context.Context, chargeID string) []Entry {
	j.mu.RLock()
	defer j.mu.RUnlock()
	var out []Entry
	for _, e := range j.entries {
		if e.ChargeID == chargeID {
			out = append(out, e)
		}
	}
	return out
}

// NetCaptured replays a charge's entries and returns what is still captured
// after refunds. Derived, never stored: a cached balance is a second source of
// truth and the two drift.
func (j *Journal) NetCaptured(ctx context.Context, chargeID string, c money.Currency) (money.Amount, error) {
	total := money.Amount{Currency: c}
	for _, e := range j.Entries(ctx, chargeID) {
		var err error
		switch e.Direction {
		case Credit:
			total, err = total.Add(e.Amount)
		case Debit:
			total, err = total.Sub(e.Amount)
		}
		if err != nil {
			return money.Amount{}, err
		}
	}
	return total, nil
}
EOF
