// Package charge creates and reads charges.
package charge

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"time"

	"github.com/entireio/acme-payments/internal/ledger"
	"github.com/entireio/acme-payments/internal/money"
	"github.com/entireio/acme-payments/internal/store"
)

const (
	StatusPending  = "pending"
	StatusCaptured = "captured"
	StatusFailed   = "failed"
)

var (
	ErrIdempotencyKeyRequired = errors.New("charge: Idempotency-Key is required")
	ErrKeyReusedWithNewBody   = errors.New("charge: Idempotency-Key reused with a different request")
)

// Service creates charges.
type Service struct {
	Store   store.Store
	Journal *ledger.Journal
	Now     func() time.Time
}

// Request is a charge creation request.
type Request struct {
	IdempotencyKey string
	Amount         money.Amount
	CustomerID     string
}

// Create charges a customer, exactly once per idempotency key.
//
// The key is REQUIRED, not optional. A payments API is called over a network
// that loses responses, so the client cannot tell a timeout from a success and
// will retry. Without a key, that retry is a second charge, and the customer
// is billed twice for one intent. Refusing the request is better than taking
// the money and arguing about it later.
//
// A replay returns the ORIGINAL charge with no new side effect. A replay whose
// body differs is an error rather than a new charge: the same key meaning two
// different amounts is a client bug, and quietly honouring the second one
// would charge an amount the first caller never agreed to.
func (s *Service) Create(ctx context.Context, req Request) (store.ChargeRecord, error) {
	if req.IdempotencyKey == "" {
		return store.ChargeRecord{}, ErrIdempotencyKeyRequired
	}

	existing, err := s.Store.FindChargeByIdempotencyKey(ctx, req.IdempotencyKey)
	if err == nil {
		if existing.AmountMinor != req.Amount.Minor || existing.Currency != req.Amount.Currency.Code {
			return store.ChargeRecord{}, fmt.Errorf("%w: key %q", ErrKeyReusedWithNewBody, req.IdempotencyKey)
		}
		return existing, nil
	}
	if !errors.Is(err, store.ErrNotFound) {
		return store.ChargeRecord{}, err
	}

	rec := store.ChargeRecord{
		ID:             newID("ch"),
		IdempotencyKey: req.IdempotencyKey,
		AmountMinor:    req.Amount.Minor,
		Currency:       req.Amount.Currency.Code,
		Status:         StatusPending,
		CreatedAt:      s.now(),
	}
	if err := s.Store.PutCharge(ctx, rec); err != nil {
		return store.ChargeRecord{}, err
	}
	return rec, nil
}

// Capture marks a pending charge captured and writes both ledger sides.
func (s *Service) Capture(ctx context.Context, chargeID, providerRef string) error {
	rec, err := s.Store.GetCharge(ctx, chargeID)
	if err != nil {
		return err
	}
	if rec.Status == StatusCaptured {
		// Providers retry webhooks, so a second capture for the same charge is
		// expected traffic, not an error. Writing the ledger pair again would
		// double the recorded revenue.
		return nil
	}
	rec.Status = StatusCaptured
	rec.ProviderRef = providerRef
	if err := s.Store.PutCharge(ctx, rec); err != nil {
		return err
	}
	amt := money.Amount{Minor: rec.AmountMinor, Currency: currencyFor(rec.Currency)}
	at := s.now()
	return s.Journal.Append(ctx,
		ledger.Entry{ID: newID("le"), ChargeID: rec.ID, Account: "cash", Direction: ledger.Credit, Amount: amt, Reason: "capture", At: at},
		ledger.Entry{ID: newID("le"), ChargeID: rec.ID, Account: "revenue", Direction: ledger.Debit, Amount: amt, Reason: "capture", At: at},
	)
}

func (s *Service) now() time.Time {
	if s.Now != nil {
		return s.Now()
	}
	return time.Now().UTC()
}

func currencyFor(code string) money.Currency {
	switch code {
	case "JPY":
		return money.JPY
	case "EUR":
		return money.EUR
	case "GBP":
		return money.GBP
	default:
		return money.USD
	}
}

func newID(prefix string) string {
	b := make([]byte, 10)
	_, _ = rand.Read(b)
	return prefix + "_" + hex.EncodeToString(b)
}
EOF
