// Package webhook receives provider callbacks.
package webhook

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"strconv"
	"strings"
	"time"
)

var (
	ErrBadSignature = errors.New("webhook: signature does not verify")
	ErrStale        = errors.New("webhook: timestamp outside tolerance")
)

// Tolerance bounds how old a signed payload may be. Without it a signature
// captured once is valid forever, so an attacker who records a single legitimate
// callback can replay it indefinitely.
const Tolerance = 5 * time.Minute

// Verifier checks provider signatures.
//
// Secrets is a SET, not one value, because rotation needs an overlap window:
// during a rotation the provider may still sign with the previous secret, and
// a verifier holding only the newest one rejects real traffic for the length
// of the rollout.
type Verifier struct {
	Secrets []string
	Now     func() time.Time
}

// Verify checks a signature header of the form "t=<unix>,v1=<hex>".
//
// Comparison is hmac.Equal, never ==. A byte-by-byte string compare returns as
// soon as it finds a difference, so its timing leaks how much of the prefix was
// right, and a few thousand attempts recover the signature.
func (v *Verifier) Verify(header string, body []byte) error {
	ts, sig, err := parseHeader(header)
	if err != nil {
		return err
	}

	now := time.Now().UTC()
	if v.Now != nil {
		now = v.Now()
	}
	age := now.Sub(ts)
	if age < -Tolerance || age > Tolerance {
		return ErrStale
	}

	signed := []byte(strconv.FormatInt(ts.Unix(), 10) + "." + string(body))
	want, err := hex.DecodeString(sig)
	if err != nil {
		return ErrBadSignature
	}
	for _, secret := range v.Secrets {
		mac := hmac.New(sha256.New, []byte(secret))
		mac.Write(signed)
		if hmac.Equal(mac.Sum(nil), want) {
			return nil
		}
	}
	return ErrBadSignature
}

func parseHeader(header string) (time.Time, string, error) {
	var tsPart, sigPart string
	for _, field := range strings.Split(header, ",") {
		k, val, ok := strings.Cut(strings.TrimSpace(field), "=")
		if !ok {
			continue
		}
		switch k {
		case "t":
			tsPart = val
		case "v1":
			sigPart = val
		}
	}
	if tsPart == "" || sigPart == "" {
		return time.Time{}, "", ErrBadSignature
	}
	secs, err := strconv.ParseInt(tsPart, 10, 64)
	if err != nil {
		return time.Time{}, "", ErrBadSignature
	}
	return time.Unix(secs, 0).UTC(), sigPart, nil
}
EOF
