package webhook

import (
	"encoding/json"
	"errors"
	"log/slog"
	"net/http"

	"github.com/entireio/acme-payments/internal/charge"
	"github.com/entireio/acme-payments/internal/store"
)

// Event is a provider callback.
type Event struct {
	Type        string `json:"type"`
	ChargeID    string `json:"charge_id"`
	ProviderRef string `json:"provider_ref"`
}

// Handler verifies and applies provider callbacks.
type Handler struct {
	Verifier *Verifier
	Charges  *charge.Service
	Log      *slog.Logger
}

// ServeHTTP applies one provider event.
//
// THE ORDERING TRAP: the provider can deliver "charge.captured" BEFORE our own
// Create has committed. Their network hop is often faster than our write, so a
// handler that treats "charge not found" as a hard error drops real captures
// under load, and the money is taken while our side says pending forever.
//
// A 404 from the store is therefore answered with 409, not 500 and not 200:
// 409 tells the provider to retry with backoff, and by the next delivery the
// charge exists. 200 would make it stop retrying and lose the event; 500 gets
// the endpoint marked unhealthy and disabled.
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	body, err := readLimited(r)
	if err != nil {
		http.Error(w, "payload too large", http.StatusRequestEntityTooLarge)
		return
	}
	if err := h.Verifier.Verify(r.Header.Get("Acme-Signature"), body); err != nil {
		http.Error(w, "bad signature", http.StatusUnauthorized)
		return
	}

	var ev Event
	if err := json.Unmarshal(body, &ev); err != nil {
		http.Error(w, "bad payload", http.StatusBadRequest)
		return
	}
	if ev.Type != "charge.captured" {
		w.WriteHeader(http.StatusNoContent)
		return
	}

	switch err := h.Charges.Capture(r.Context(), ev.ChargeID, ev.ProviderRef); {
	case err == nil:
		w.WriteHeader(http.StatusNoContent)
	case errors.Is(err, store.ErrNotFound):
		h.Log.Info("capture arrived before the charge was visible; asking for a retry",
			"charge_id", ev.ChargeID)
		http.Error(w, "charge not yet visible, retry", http.StatusConflict)
	default:
		http.Error(w, "internal error", http.StatusInternalServerError)
	}
}

const maxWebhookBytes = 1 << 20

func readLimited(r *http.Request) ([]byte, error) {
	defer r.Body.Close()
	limited := http.MaxBytesReader(nil, r.Body, maxWebhookBytes)
	buf := make([]byte, 0, 4096)
	tmp := make([]byte, 4096)
	for {
		n, err := limited.Read(tmp)
		buf = append(buf, tmp[:n]...)
		if err != nil {
			if err.Error() == "EOF" {
				return buf, nil
			}
			return nil, err
		}
	}
}
EOF

