// Package api wires HTTP routes onto the payment services.
package api

import (
	"encoding/json"
	"errors"
	"log/slog"
	"net/http"

	"github.com/entireio/acme-payments/internal/charge"
	"github.com/entireio/acme-payments/internal/ledger"
	"github.com/entireio/acme-payments/internal/money"
	"github.com/entireio/acme-payments/internal/store"
	"github.com/entireio/acme-payments/internal/webhook"
)

// Server holds the dependencies every route needs.
type Server struct {
	Charges *charge.Service
	Journal *ledger.Journal
	Hook    *webhook.Handler
	Log     *slog.Logger
}

// Routes returns the mux for the service.
func (s *Server) Routes() *http.ServeMux {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /v1/charges", s.createCharge)
	mux.HandleFunc("GET /v1/charges/{id}", s.getCharge)
	mux.HandleFunc("GET /v1/charges/{id}/ledger", s.getLedger)
	mux.Handle("POST /v1/webhooks/provider", s.Hook)
	mux.HandleFunc("GET /healthz", s.health)
	return mux
}

type createChargeRequest struct {
	AmountMinor int64  `json:"amount_minor"`
	Currency    string `json:"currency"`
	CustomerID  string `json:"customer_id"`
}

func (s *Server) createCharge(w http.ResponseWriter, r *http.Request) {
	var req createChargeRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad payload", http.StatusBadRequest)
		return
	}
	amt, err := money.New(req.AmountMinor, currencyFor(req.Currency))
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	rec, err := s.Charges.Create(r.Context(), charge.Request{
		IdempotencyKey: r.Header.Get("Idempotency-Key"),
		Amount:         amt,
		CustomerID:     req.CustomerID,
	})
	switch {
	case errors.Is(err, charge.ErrIdempotencyKeyRequired):
		// 400, not 422: the request is unprocessable before we look at the body.
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	case errors.Is(err, charge.ErrKeyReusedWithNewBody):
		http.Error(w, err.Error(), http.StatusConflict)
		return
	case err != nil:
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	writeJSON(w, http.StatusCreated, rec)
}

func (s *Server) getCharge(w http.ResponseWriter, r *http.Request) {
	rec, err := s.Charges.Store.GetCharge(r.Context(), r.PathValue("id"))
	if errors.Is(err, store.ErrNotFound) {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	writeJSON(w, http.StatusOK, rec)
}

func (s *Server) getLedger(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.Journal.Entries(r.Context(), r.PathValue("id")))
}

func (s *Server) health(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(v)
}

func currencyFor(code string) money.Currency {
	switch code {
	case "JPY":
		return money.JPY
	case "EUR":
		return money.EUR
	case "GBP":
		return money.GBP
	default:
		return money.USD
	}
}
