func sign(secret string, ts time.Time, body []byte) string {
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write([]byte(strconv.FormatInt(ts.Unix(), 10) + "." + string(body)))
	return "t=" + strconv.FormatInt(ts.Unix(), 10) + ",v1=" + hex.EncodeToString(mac.Sum(nil))
}

func TestValidSignatureVerifies(t *testing.T) {
	now := time.Unix(1700000000, 0).UTC()
	v := &Verifier{Secrets: []string{"whsec_a"}, Now: func() time.Time { return now }}
	body := []byte(`{"type":"charge.captured"}`)
	if err := v.Verify(sign("whsec_a", now, body), body); err != nil {
		t.Fatal(err)
	}
}

// The reason Secrets is a set: during rotation the provider still signs with
// the old one, and rejecting that traffic is an outage.
func TestOldSecretStillVerifiesDuringRotation(t *testing.T) {
	now := time.Unix(1700000000, 0).UTC()
	v := &Verifier{Secrets: []string{"whsec_new", "whsec_old"}, Now: func() time.Time { return now }}
	body := []byte(`{"type":"charge.captured"}`)
	if err := v.Verify(sign("whsec_old", now, body), body); err != nil {
		t.Fatalf("a payload signed with the previous secret must still verify: %v", err)
	}
}

// Without the tolerance, one captured signature is valid forever.
func TestReplayOutsideToleranceIsRejected(t *testing.T) {
	signedAt := time.Unix(1700000000, 0).UTC()
	now := signedAt.Add(Tolerance + time.Minute)
	v := &Verifier{Secrets: []string{"whsec_a"}, Now: func() time.Time { return now }}
	body := []byte(`{"type":"charge.captured"}`)
	if err := v.Verify(sign("whsec_a", signedAt, body), body); !errors.Is(err, ErrStale) {
		t.Fatalf("want ErrStale for a replayed payload, got %v", err)
	}
}

func TestTamperedBodyFailsVerification(t *testing.T) {
	now := time.Unix(1700000000, 0).UTC()
	v := &Verifier{Secrets: []string{"whsec_a"}, Now: func() time.Time { return now }}
	header := sign("whsec_a", now, []byte(`{"amount_minor":100}`))
	if err := v.Verify(header, []byte(`{"amount_minor":100000}`)); !errors.Is(err, ErrBadSignature) {
		t.Fatalf("want ErrBadSignature when the body changed, got %v", err)
	}
}
