// TestBrainRecallArgsAreAcceptedByTheRecallCommand exists because the AST
// guard above could not have caught the bug it was written alongside.
//
// brain_recall was shipped passing --limit. The recall command's flag is --k,
// so EVERY call failed with "unknown flag: --limit" before reading a single
// fact, while TestEveryDeclaredToolIsRouted stayed green: declaration and
// dispatch both existed, and nothing executed the thing.
//
// This drives the real command with the real argument list. It cannot assert
// the facts that come back -- there is no brain here -- but it does assert the
// one failure mode that makes the tool useless: the command refusing its own
// arguments.
func TestBrainRecallArgsAreAcceptedByTheRecallCommand(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name  string
		limit int
		want  int
	}{
		{"in range", 5, 5},
		{"clamped up", 0, 1},
		{"clamped down", 10000, recallMaxK},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			limit := tc.limit
			if limit < 1 {
				limit = 1
			}
			if limit > recallMaxK {
				limit = recallMaxK
			}
			if limit != tc.want {
				t.Fatalf("clamp produced %d, want %d", limit, tc.want)
			}

			cmd := newRecallCommand(Options{})
			var out bytes.Buffer
			cmd.SetOut(&out)
			cmd.SetErr(&out)
			cmd.SetContext(context.Background())
			cmd.SetArgs([]string{"q", "--json", "--k", strconv.Itoa(limit), "--read-only-semantic-cache"})

			// Execute will fail for lack of a brain; what must NOT happen is a
