func renderStatusOnboardingBlock(out io.Writer, render *tui.Renderer, report brainStatusReport, brainCmd string) {
	brainCmd = setupBrainCommand(brainCmd)
	onboarding := report.Onboarding
	if onboarding == nil {
		return
	}
