func TestWindowsRootsComeFromTheVariablesWindowsActuallyUses(t *testing.T) {
	t.Parallel()
	env := map[string]string{
		"TMP":    `C:\Users\someone\AppData\Local\Temp`,
		"TEMP":   `C:\Users\someone\AppData\Local\Temp`,
