// install sitting silent and no indication why.

func TestConsentNeedsBothEndsOfTheTerminal(t *testing.T) {
	t.Parallel()

	// A pipe: open, readable, and never EOFs on its own. This is the shape
	// that hangs, and `script`-style wrapping is how it reaches a run whose
	// stdout looks interactive.
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = r.Close(); _ = w.Close() })

	if setupCanAskAHuman(true, r) {
		t.Fatal("stdout being a terminal does not make a pipe into a person; this is the hang")
	}
	if setupCanAskAHuman(true, &bytes.Buffer{}) {
		t.Fatal("a buffer is not a person")
	}
	if setupCanAskAHuman(true, strings.NewReader("y\n")) {
		t.Fatal("a canned answer is not consent")
	}

	// And the other direction: a real terminal on stdin does not help when
	// nothing can be printed to ask with.
	if setupCanAskAHuman(false, os.Stdin) {
		t.Fatal("no output means the question is never seen, whatever stdin is")
	}
}

// The gate must default to NOT asking. Being wrong that way costs a skipped
