// --- the board is LIVE -------------------------------------------------
//
// The board is a file Claude edits while it works. A pane that read once, at
// open time, shows a photograph of the moment someone stopped trusting their
// memory -- which is precisely when they opened it.

test('a board edited after the pane opened is redrawn with the new state', async ($, on) => {
  let current = boardJson([{ id: 'T-01', title: 'First task', status: 'doing', owner: 'claude' }])
  harness(on, () => ({ value: current }))

  await $.command.run({ command: 'todo', args: '' })
  const before = await $.ui.mount(PANE)
  expect(await before.find({ type: 'Text', text: 'First task' })).toBeDefined()

  // Claude edits the file mid-task. Nobody types /todo.
  current = boardJson([{ id: 'T-02', title: 'Second task', status: 'blocked', owner: 'user' }])

  const after = await $.ui.mount(PANE)
  expect(await after.find({ type: 'Text', text: 'Second task' })).toBeDefined()
  expect(await after.find({ type: 'Text', text: 'First task' })).toBeUndefined()
  expect(await after.find({ type: 'Text', text: '1 waiting on you' })).toBeDefined()
})

// The loop guard. A write redraws the readers, so a refresh that wrote on
// every render would redraw, refresh, write, redraw -- forever. Writing only
// on CHANGED bytes is the whole reason that cannot happen, so it is asserted
// directly rather than inferred from the pane looking right.
test('an unchanged board file is read but never re-published', async ($, on) => {
  const stable = boardJson([{ id: 'T-01', title: 'Stable task', status: 'doing', owner: 'claude' }])
  let reads = 0
  const writes: unknown[] = []
  harness(on, () => {
    reads += 1
    return { value: stable }
  })
  on('state.update', ($$, e) => {
    writes.push(e)
    return undefined
  })

  await $.command.run({ command: 'todo', args: '' })
  const writesAfterFirstLoad = writes.length
  const readsAfterFirstLoad = reads

  await $.ui.mount(PANE)
  await $.ui.mount(PANE)
  await $.ui.mount(PANE)

  expect(reads).toBeGreaterThan(readsAfterFirstLoad)
  if (writes.length !== writesAfterFirstLoad) {
    throw new Error(
      `unchanged bytes were published again (${writes.length - writesAfterFirstLoad} writes across 3 renders): ` +
        'each write redraws the readers, so this is a render loop',
    )
  }
})

// A poll can catch the file mid-save. Blanking a board that was good a moment
// ago, because a writer is between open and rename, would make the board
// flicker between real and broken -- worse than briefly lagging.
test('a half-written board does not blank a board that was already good', async ($, on) => {
  let current = boardJson([{ id: 'T-01', title: 'Good task', status: 'doing', owner: 'claude' }])
  harness(on, () => ({ value: current }))

  await $.command.run({ command: 'todo', args: '' })
