  current = boardJson([{ id: 'T-02', title: 'Saved task', status: 'doing', owner: 'claude' }])
  const after = await $.ui.mount(PANE)
  expect(await after.find({ type: 'Text', text: 'Saved task' })).toBeDefined()
})
