// One recorded brain call. `outcome` is the whole point: an empty answer is not
// an answer, and `note` carries brain's own blind_spot explaining why it was empty.
export type BrainCall = {
  turn: number
  verb: string
  via: 'mcp' | 'cli'
  query: string
  outcome: 'hit' | 'empty' | 'error'
  detail: string
  note: string
}

// One day of brain usage, as collect-usage.py reports it. Days with no events
// are absent from the map, not zero-filled: the pane fills the window itself,
// because a chart that silently omits quiet days makes a gap look like use.
export type BrainUsageDay = {
  mcp: number
  bash: number
  answered: number
  empty: number
  failed: number
  tools: Record<string, number>
}

// `null` until /brainusage has run: an empty object would draw as "brain was
// never used", the false negative this mod exists to prevent. `error` carries
// the collector's stderr so a failed scan is visible instead of looking quiet.
export type BrainUsage = {
  loading: boolean
  days: number
  data?: {
    generated_at: string
    window_days: number
    window_start: string
    files_scanned: number
    events: number
    days: Record<string, BrainUsageDay>
  } | null
  error?: string
} | null

} | null

declare module 'claude-code' {
  interface PluginState {
    'brain-memory': {
      calls: BrainCall[]
      turn: number
      usage: BrainUsage
    }
  }
}

