	})
}

func seedBranchFact(t *testing.T, brainDir, branch, id string, now time.Time) {
	t.Helper()
	if err := writeFacts(brainDir, branch, []factRecord{{
		ID: id, Paths: []string{"preferences.style.x"}, Text: "The user prefers table-driven tests.",
		Branch: branch, Origin: "distilled", Status: "active", UpdatedAt: now,
	}}); err != nil {
		t.Fatalf("write facts on %s: %v", branch, err)
	}
}

// TestFactOnOneBranchDoesNotReindexAnotherBranchsSessions is the guard for the
// whole change. Before it, the assertion below failed for BOTH sessions.
func TestFactOnOneBranchDoesNotReindexAnotherBranchsSessions(t *testing.T) {
	now := time.Date(2026, 8, 9, 12, 0, 0, 0, time.UTC)
	brainDir := twoBranchCorpusFixture(t, now)
	if err := buildPatternCorpus(brainDir, now); err != nil {
		t.Fatal(err)
	}
	before := patternCorpusIndexedSHAs(t, brainDir)
	if len(before) < 2 {
		t.Fatalf("expected both branches indexed, got %v", before)
	}

	// A fact on `feature` only. Nothing about main's session changed.
	seedBranchFact(t, brainDir, "feature", "fact:feature-only", now.Add(time.Minute))
	if err := buildPatternCorpus(brainDir, now.Add(2*time.Minute)); err != nil {
		t.Fatal(err)
	}

	after := patternCorpusIndexedSHAs(t, brainDir)
	if len(after) != len(before) {
		t.Fatalf("session set changed: %v -> %v", before, after)
	}
	// Both must still be present and byte-identical: the point is that main's
	// session was SKIPPED, not that it was rebuilt to the same bytes. The skip
	// itself is asserted by the sibling test below, which counts the work.
	for id, sha := range before {
		if after[id] != sha {
			t.Fatalf("session %s was re-indexed by a fact on another branch: %q -> %q", id, sha, after[id])
		}
	}
}

// TestFactOnABranchStillReindexesThatBranchsSessions is the other half, and the
// one that stops the fix being "skip everything". A fact on a branch MUST
// still rebuild that branch's links, or the speedup is a correctness bug.
func TestFactOnABranchStillReindexesThatBranchsSessions(t *testing.T) {
	now := time.Date(2026, 8, 9, 12, 0, 0, 0, time.UTC)
	brainDir := twoBranchCorpusFixture(t, now)
	if err := buildPatternCorpus(brainDir, now); err != nil {
		t.Fatal(err)
	}
	db, err := openPatternCorpusMutableDB(brainDir)
	if err != nil {
		t.Fatal(err)
	}
	stored := corpusMeta(db, patternCorpusFactsMetaKey("feature"))
	db.Close()

	seedBranchFact(t, brainDir, "feature", "fact:feature-only", now.Add(time.Minute))
	if err := buildPatternCorpus(brainDir, now.Add(2*time.Minute)); err != nil {
		t.Fatal(err)
	}

	db2, err := openPatternCorpusMutableDB(brainDir)
	if err != nil {
		t.Fatal(err)
	}
	defer db2.Close()
	if got := corpusMeta(db2, patternCorpusFactsMetaKey("feature")); got == stored {
		t.Fatalf("feature's fact fingerprint did not change after a fact was written to it (%q)", got)
	}
	if got := corpusMeta(db2, patternCorpusFactsMetaKey("main")); got == "" {
		t.Fatal("main's fact fingerprint was never recorded, so main can never be skipped")
	}
}

// TestPatternCorpusFactsMetaKeyCannotCollide: branch names contain slashes and
// arbitrary bytes, and the meta table is a flat key space shared with keys like
// "facts_fingerprint". An interpolated branch name would collide.
func TestPatternCorpusFactsMetaKeyCannotCollide(t *testing.T) {
	t.Parallel()
	seen := map[string]string{}
	for _, branch := range []string{
		"main", "feature", "feature/x", "feature/x/y", "", "facts_fingerprint",
		"facts_fingerprint/main", "../escape", "a b", "日本語",
	} {
		key := patternCorpusFactsMetaKey(branch)
		if prior, dup := seen[key]; dup {
			t.Fatalf("branches %q and %q share the meta key %q", prior, branch, key)
		}
		seen[key] = branch
		for _, reserved := range []string{"schema_version", "pattern_indexer_version", "facts_fingerprint", "repo_key", "sessions_fingerprint", "privacy_policy_identity", "generated_at"} {
			if key == reserved {
				t.Fatalf("branch %q produced the reserved meta key %q", branch, reserved)
			}
		}
	}
}
